'use strict';
(() => {
function create({data,esc,shell,readingBar,questionPath=()=>''}) {
 const topics=data.topics;
 const topicPositions=new Map();
 const byId=Object.fromEntries([...data.subjects.flatMap(s=>s.questions.map(q=>({...q,subject:s.key,subjectName:s.name}))),...(data.comprehensive?.questions||[])].map(q=>[q.id,q]));
 const topicById=Object.fromEntries(topics.map(t=>[t.id,t]));
 const topicUrl=topic=>'#topics/'+topic.subject+'/'+topic.group;
 function homePanel(){
  return `<section class="paper guided-home" aria-label="规范作答学习"><div><h2>先看规范作答，顺着思路背。</h2><p>题目直接带着答案读：看条件、认知识点，再沿推导复述。</p><a href="#topics/micro/05">从垄断、串联垄断到 n 厂商古诺</a></div><div class="guided-actions">${data.subjects.map(s=>`<button class="btn primary" data-action="study-day" data-sub="${s.key}">跟读${s.name}今日10题</button>`).join('')}<a class="btn" href="#topics">查看专题串联</a></div></section>`;
 }
 function topicLink(q,label='本题所在专题'){return `<a class="btn" href="${topicUrl(topicById[q.subject+'-'+q.group])}">${label}</a>`;}
 function questionLinks(ids,topic){return `<div class="topic-questions">${ids.map(id=>`<button class="btn" data-action="study-single" data-id="${id}" data-topic="${topic.id}" title="${esc(byId[id].title)}">看规范作答 ${id}</button>`).join('')}</div>`;}
 function topicCards(topic){return topic.card_ids.length?`<section class="topic-card-links"><h2>回查公式与概念</h2><div class="actions">${topic.card_ids.map(id=>{const card=data.recall.cards.find(c=>c.id===id);return `<button class="btn" data-action="recall-card" data-id="${id}" data-return="topics/${topic.subject}/${topic.group}">${esc(card.title)}</button>`;}).join('')}</div></section>`:'';}
 function renderTopics(){
  const [,subjectKey,group]=location.hash.slice(1).split('/');
  const subject=data.subjects.find(s=>s.key===subjectKey)||data.subjects[0];
  const topic=topicById[subject.key+'-'+group];
  if(topic){renderTopic(topic);return;}
  shell(`<p><a class="btn primary" href="#methods">宏微观作答速查与闭卷检测</a></p><div class="page-heading"><div><h1>专题串联</h1><p>从一个知识点走到下一种模型，记住条件怎样变，作答怎样接。</p></div><a class="btn" href="#bank">按题找规范作答</a></div><nav class="topic-subjects tabs" aria-label="专题科目">${data.subjects.map(s=>`<a class="tab ${s.key===subject.key?'active':''}" href="#topics/${s.key}" ${s.key===subject.key?'aria-current="page"':''}>${s.name}</a>`).join('')}</nav><section class="paper topic-index">${topics.filter(t=>t.subject===subject.key).map(t=>`<article class="topic-index-row"><div class="topic-index-number">${t.group}</div><div><h2><a href="${topicUrl(t)}">${esc(t.title)}</a></h2><p class="topic-group-title">${esc(t.group_title)}</p><ol class="topic-route">${t.stages.map(stage=>`<li>${esc(stage.title)}</li>`).join('')}</ol></div><a class="btn primary" href="${topicUrl(t)}">展开串联</a></article>`).join('')}</section><p class="topic-provenance">专题内容为编者基于已交付题库和手册的串联整理；各篇注明补充推导与适用条件。</p>`,'topics');
 }
 function renderTopic(topic){
  const position=topicPositions.get(topic.id)||{index:0,all:false};
  shell(`<div class="topic-reader"><div class="topic-back"><a class="btn flat" href="#topics/${topic.subject}">返回${data.subjects.find(s=>s.key===topic.subject).name}专题</a><button class="btn primary" data-action="study-topic" data-id="${topic.id}">按主线跟读本专题题目</button></div>${readingBar()}${['micro','macro'].includes(topic.subject)?`<p class="actions"><a class="btn" href="#maps/${topic.subject}/${topic.group}/mind">在知识导图中查看本专题</a><a class="btn primary" href="#methods/${topic.subject}/${topic.group}">作答速查与闭卷检测</a></p>`:''}<article class="paper topic-paper"><p class="topic-group-title">${esc(topic.group_title)}</p><h1>${esc(topic.title)}</h1><div class="rich topic-lead">${topic.lead_html}</div><nav class="topic-jumps" aria-label="本专题学习顺序">${topic.stages.map((stage,index)=>`<button data-action="topic-section" data-index="${index}" ${!position.all&&position.index===index?'aria-current="step"':''}><span>${index+1}</span>${esc(stage.title)}</button>`).join('')}</nav><div class="topic-display-control"><p>一次读一个环节，公式与推导分行对照。</p><button class="btn" data-action="topic-expand-all">${position.all?'回到逐环节学习':'展开全部环节'}</button></div><ol class="topic-stages">${topic.stages.map((stage,index)=>`<li class="topic-stage" id="topic-stage-${index}" ${!position.all&&position.index!==index?'hidden':''}><h2 tabindex="-1"><span>${index+1}</span>${esc(stage.title)}</h2><div class="rich">${stage.explanation_html}</div>${stage.question_ids.length?questionLinks(stage.question_ids,topic):'<p class="small muted">本环节为补充模型，按这里列明的假设学习。</p>'}</li>`).join('')}</ol><div class="topic-step-controls" ${position.all?'hidden':''}><button class="btn" data-action="topic-prev" ${position.index===0?'disabled':''}>上一环节</button><span>第 ${position.index+1} / ${topic.stages.length} 环节</span><button class="btn primary" data-action="topic-next">${position.index===topic.stages.length-1?'看模型对照与背诵主线':'下一环节'}</button></div>${topic.comparison_md?`<details class="topic-comparison"><summary>放在一起比较模型</summary><div class="rich">${topic.comparison_html}</div></details>`:''}<details class="topic-boundaries"><summary>先守住这些条件</summary><div class="rich">${topic.boundaries_html}</div></details><details class="topic-recall"><summary>沿这条线复述</summary><div class="rich">${topic.recall_html}</div></details>${topicCards(topic)}<details class="topic-all-questions"><summary>本专题关联的 ${topic.source_question_ids.length} 道题</summary>${questionLinks(topic.source_question_ids,topic)}</details><details class="source"><summary>整理依据与补充说明</summary><p>${esc(topic.editorial_note)}</p><p>${esc(topic.source_note)}</p><p>对应题目保留原题干、完整解答与题源；串联中的一般模型须按各题条件重新代入。</p></details></article><div class="topic-footer"><a class="btn" href="#topics/${topic.subject}">继续选专题</a><button class="btn primary" data-action="study-topic" data-id="${topic.id}">跟读对应题目的规范作答</button></div></div>`,'topics');
 }
 function reviewCardLinks(guide){return guide.related_card_ids?.length?`<div class="actions exam-related-cards">${guide.related_card_ids.map(id=>`<button class="btn" data-action="recall-card" data-id="${id}" data-return="practice">回查：${esc(data.recall.cards.find(c=>c.id===id).title)}</button>`).join('')}</div>`:'';}
 function renderQuestion(q,s){
  const topic=topicById[s.topicId]||topicById[q.subject+'-'+q.group],guide=window.SolutionReader.guide(q);
  shell(`<div class="practice-layout split-workspace guided-practice ${q.diagrams?.length&&s.revealed?'with-diagrams':''}"><div class="exercise-top"><a class="btn flat" href="${topicUrl(topic)}">返回专题串联</a><button class="btn" data-action="study-independent">独立做这道题</button></div>${readingBar()}<aside class="paper question-rail" aria-label="本组题目"><div class="rail-title">${esc(s.mode)}</div><div class="rail-ids">${s.ids.map((id,index)=>`<button class="qchip ${s.index===index?'current':''}" data-action="jump" data-index="${index}" ${s.index===index?'aria-current="step"':''} title="${esc(byId[id].title)}">${id}</button>`).join('')}</div><div class="rail-meta"><span class="rail-progress">第 ${s.index+1}/${s.ids.length} 题</span></div></aside><div class="question-column" tabindex="0" role="region" aria-label="题目与辅助图形，可滚动查看"><article class="paper question-paper"><div class="exercise-meta"><span class="q-id">${q.id}</span><span>${q.subjectName}</span><span>规范作答跟读</span></div><div class="exercise-heading"><h1 id="question-heading" tabindex="-1">${esc(q.title)}</h1></div><div class="rich prompt" id="question-prompt">${q.training?.prompt_html||guide.prompt_html||q.prompt_html}</div>${window.ExamReview?.promptNote(q)||''}${guide.corrections?`<aside class="study-correction" role="note"><h2>本题勘误已用于规范作答</h2>${guide.corrections.map(c=>`<p><strong>${esc(c.title)}</strong><br>${esc(c.explanation)}</p>`).join('')}</aside>`:''}</article>${window.StudyDiagrams.renderPanel(q,{revealed:s.revealed})}</div><div class="exercise"><article class="paper exercise-paper study-paper"><section class="study-outline" id="study-outline"><h2>这道题怎样起笔</h2><div class="rich">${guide.method_html||q.outline_html}</div><button class="btn" data-action="study-reveal" aria-expanded="${s.revealed}" aria-controls="study-answer">${s.revealed?'遮住答案，按主线复述':'再看规范作答'}</button></section><section id="study-answer" class="study-answer" ${s.revealed?'':'hidden'}><h2>规范作答</h2><p class="small muted">${window.ExamReview?.note(guide)||'作答正文来自既有题库。'}</p>${window.SolutionReader.render(q,{progress:s.solutionLines,guide,readerId:'guided'})}${questionPath(q.id)}<details class="study-applications"><summary>回看知识点在本题里的用法</summary><h2>知识点在本题里怎么用</h2><ul class="knowledge-list">${guide.knowledge.map(item=>`<li><h3 class="rich">${item.title_html}</h3><div class="rich">${item.explanation_html}</div>${item.card_ids.length?`<div class="actions">${item.card_ids.map(id=>`<button class="btn" data-action="recall-card" data-id="${id}" data-return="practice">回查：${esc(data.recall.cards.find(c=>c.id===id).title)}</button>`).join('')}</div>`:''}</li>`).join('')}</ul>${reviewCardLinks(guide)}</details><details class="study-pitfalls"><summary>查看条件与易错</summary><section class="pitfalls"><h2>条件与易错</h2><div class="rich">${guide.pitfalls_html||q.pitfalls_html}</div></section></details><details class="study-recap"><summary>查看整题背诵主线</summary><section class="knowledge-chain"><h2>沿这条线，把答案复述出来</h2><div class="rich">${guide.recap_html||q.solution.recap_html}</div></section></details></section><aside class="study-to-topic"><div><h2>把这一题接回整章</h2><p>${esc(topic.title)}</p></div><a class="btn" href="${topicUrl(topic)}">查看专题串联</a></aside><p class="study-record-note">跟读和翻页只保存阅读位置。准备好独立复现时，再进入作答并自评。</p><details class="source"><summary>题源与整理说明</summary>${q.source_refs.map(ref=>`<p>${esc(ref.exam_id)}；${esc(ref.source.split('/').pop())}，PDF物理页 ${esc(ref.pages)}。<br>${esc(ref.note)}</p>`).join('')}<p>知识点标签和串联属于编者学习整理，不是教材逐字引文。</p>${window.ExamReview?.source(q)||(guide.corrections?`<details class="study-original"><summary>查看保留的原解答（含已说明的错误）</summary><div class="rich">${q.answer_html}</div></details>`:'')}</details></article><nav class="exercise-bottom" aria-label="题目翻页"><button class="btn" data-action="prev" ${s.index===0?'disabled':''}>上一题</button><span>跟读 ${s.index+1} / ${s.ids.length} 题</span><button class="btn ink" data-action="next">${s.index===s.ids.length-1?'结束跟读':'下一题'}</button></nav></div></div>`,'practice');
 }
 function action(button){
  const a=button.dataset.action;if(!['topic-section','topic-next','topic-prev','topic-expand-all'].includes(a))return false;
  const [,subject,group]=location.hash.slice(1).split('/'),topic=topicById[subject+'-'+group];if(!topic)return false;
  const position=topicPositions.get(topic.id)||{index:0,all:false};
  if(a==='topic-next'&&position.index===topic.stages.length-1){for(const area of document.querySelectorAll('.topic-comparison,.topic-recall'))area.open=true;const target=document.querySelector('.topic-comparison>summary,.topic-recall>summary');target?.scrollIntoView({block:'start'});target?.focus({preventScroll:true});return true;}
  if(a==='topic-expand-all')position.all=!position.all;
  else{position.index=Math.max(0,Math.min(topic.stages.length-1,a==='topic-section'?Number(button.dataset.index):position.index+(a==='topic-next'?1:-1)));position.all=false;}
  topicPositions.set(topic.id,position);renderTopic(topic);
  const heading=document.querySelector('#topic-stage-'+position.index+' h2');heading?.scrollIntoView({block:'start'});heading?.focus({preventScroll:true});return true;
 }
 return {homePanel,topicLink,renderTopics,renderQuestion,action};
}
window.StudyGuide={create};
})();
